  static const lessons = <EnglishAdvancedLesson>[
    EnglishAdvancedLesson(level:"A2",number:5,title:"Planning a Family Dinner",titleArabic:"التخطيط لعشاء عائلي",storyTitle:"Planning a Family Dinner",storyTitleArabic:"التخطيط لعشاء عائلي",paragraphs:<String>["Salma made a shopping list for the family dinner. She checked the cupboard and saw that they needed rice and vegetables. Her mother was preparing soup, and her brother offered to make a salad. They needed fresh ingredients before the guests arrived.","At the grocery store, Salma compared tomatoes and carrots. She put food in a basket and chose a carton of milk. At the payment counter, she checked the total and kept the change. On the way home, she bought a fresh cucumber.","The family set the table together. Salma washed the vegetables while her brother made the salad. Their mother served the soup when their grandparents arrived. Everyone enjoyed the dinner, and Salma felt proud that her plan had worked."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("shopping list","قائمة تسوق"),EnglishAdvancedWord("cupboard","خزانة مطبخ"),EnglishAdvancedWord("rice","أرز"),EnglishAdvancedWord("vegetables","خضروات"),EnglishAdvancedWord("soup","حساء"),EnglishAdvancedWord("salad","سلطة"),EnglishAdvancedWord("ingredients","مكونات"),EnglishAdvancedWord("grocery store","بقالة"),EnglishAdvancedWord("tomatoes","طماطم"),EnglishAdvancedWord("carrots","جزر"),EnglishAdvancedWord("basket","سلة"),EnglishAdvancedWord("carton","عبوة كرتونية")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("dining table","طاولة طعام"),EnglishAdvancedWord("cutlery","أدوات مائدة"),EnglishAdvancedWord("table setting","ترتيب المائدة"),EnglishAdvancedWord("measuring cup","كوب قياس"),EnglishAdvancedWord("saucepan","قدر صغير"),EnglishAdvancedWord("vegetable peeler","مقشرة خضروات"),EnglishAdvancedWord("shopping trolley","عربة تسوق"),EnglishAdvancedWord("meal preparation","تحضير وجبة"),EnglishAdvancedWord("grocery receipt","إيصال بقالة"),EnglishAdvancedWord("fresh produce","محاصيل طازجة"),EnglishAdvancedWord("portion size","حجم الحصة"),EnglishAdvancedWord("family gathering","تجمع عائلي")],grammarTitle:"Quantifiers for food and shopping",grammarArabic:"نستخدم some في جمل الإثبات والعروض، وany في الأسئلة والنفي غالبًا. نقول How many carrots؟ مع المعدود وHow much rice؟ مع غير المعدود. لا تستخدم a قبل rice غير المعدودة.",grammarExamples:<String>["We need some rice.","Do we have any milk?","How many carrots should we buy?"],listening:"Hello, everyone. The family dinner will begin at seven on Saturday. Please tell us by Friday if you cannot eat dairy products, because one dish contains cheese. We will also serve vegetable soup and salad without milk. We need to know how many guests are coming so we can buy the right amount of food. You do not need to bring anything, although a small dessert would be welcome.",listeningQuestion:"Why must guests reply by Friday?",listeningOptions:<String>["To choose a film","To plan food quantities","To buy a train ticket"],listeningAnswer:1,readingQuestion:"What did Salma prepare before going shopping?",readingOptions:<String>["A shopping list","A train ticket","A new recipe book"],readingAnswer:0,writingCue:"Salma carried the food in a ____.",writingAnswer:"basket"),
    EnglishAdvancedLesson(level:"B1",number:3,title:"A Team Project",titleArabic:"مشروع الفريق",storyTitle:"A Team Project",storyTitleArabic:"مشروع الفريق",paragraphs:<String>["Students were asked to build a model bridge for a science exhibition. Their team leader, Yusuf, divided the assignment into research, construction and public explanation. Each person had different strengths, but everyone needed to follow a shared plan.","During the first meeting, a disagreement arose about materials. Hana suggested cardboard, while Yusuf preferred wooden sticks. The team compared the cost and durability of each option and agreed on a combination that suited their limited budget.","When the bridge began to bend under pressure, students examined the supports and recorded the result. Instead of blaming one another, they made a careful revision. Their teacher encouraged them to report the failed experiment honestly and explain what they had learned.","At the exhibition, the new model supported the required weight. The judges praised the group's cooperation and its clear explanation of the improvements. Yusuf realized that responsible leadership meant listening to others and admitting mistakes."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("model bridge","نموذج جسر"),EnglishAdvancedWord("science exhibition","معرض علمي"),EnglishAdvancedWord("team leader","قائد فريق"),EnglishAdvancedWord("assignment","تكليف"),EnglishAdvancedWord("construction","إنشاء"),EnglishAdvancedWord("disagreement","خلاف"),EnglishAdvancedWord("cardboard","كرتون مقوى"),EnglishAdvancedWord("durability","متانة"),EnglishAdvancedWord("pressure","ضغط"),EnglishAdvancedWord("supports","دعامات"),EnglishAdvancedWord("revision","تنقيح"),EnglishAdvancedWord("cooperation","تعاون")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("prototype","نموذج أولي"),EnglishAdvancedWord("blueprint","مخطط تصميم"),EnglishAdvancedWord("structural strength","قوة هيكلية"),EnglishAdvancedWord("load test","اختبار التحمل"),EnglishAdvancedWord("task delegation","تفويض مهام"),EnglishAdvancedWord("mechanical stress","إجهاد ميكانيكي"),EnglishAdvancedWord("measurement scale","مقياس قياس"),EnglishAdvancedWord("engineering principle","مبدأ هندسي"),EnglishAdvancedWord("test condition","شرط اختبار"),EnglishAdvancedWord("group consensus","توافق الفريق"),EnglishAdvancedWord("joint decision","قرار مشترك"),EnglishAdvancedWord("design tolerance","حد تحمل التصميم"),EnglishAdvancedWord("experimental failure","فشل تجريبي"),EnglishAdvancedWord("technical explanation","شرح تقني"),EnglishAdvancedWord("work allocation","توزيع العمل"),EnglishAdvancedWord("collaborative problem solving","حل جماعي"),EnglishAdvancedWord("material selection","اختيار مواد"),EnglishAdvancedWord("final demonstration","عرض عملي نهائي")],grammarTitle:"Modals for duty, advice and possibility",grammarArabic:"تستخدم must للإلزام، وhave to للضرورة، وshould للنصيحة، وcould للاقتراح. بعدها يأتي الفعل الأساسي مباشرة: We should test it، وليس should to test.",grammarExamples:<String>["The bridge must support the required load.","We have to finish by Friday.","We could test another material."],listening:"Good morning, teams. Your models will be evaluated for strength, originality and clarity of explanation. Each group must submit an experiment log describing at least one difficulty and how you solved it. A strong result is useful, but a model without an explanation will not receive full marks. If your bridge breaks during testing, do not hide the result. Describe what went wrong and how you changed your design. The judges will ask questions after each presentation, so everyone should be prepared to explain one part of the project.",listeningQuestion:"What should every team include in its experiment log?",listeningOptions:<String>["Only the final score","A problem and its solution","Its favorite subject"],listeningAnswer:1,readingQuestion:"How did the students react when the bridge bent?",readingOptions:<String>["They adjusted the supports","They abandoned the project","They bought a completed bridge"],readingAnswer:0,writingCue:"The bridge bent under too much ____.",writingAnswer:"pressure")
  ];
